(function(){
  'use strict';
  const LF=window.LFArt,$=id=>document.getElementById(id),$$=(q,r=document)=>[...r.querySelectorAll(q)];
  let editor,renderer,started=false;
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function status(message,type=''){const el=$('statusText');if(el){el.textContent=message;el.className=type==='ok'?'status-ok':type==='warn'?'status-warn':'';}}
  function hsvToRgb(h,s,v){const c=v*s,x=c*(1-Math.abs((h/60)%2-1)),m=v-c;let r=0,g=0,b=0;if(h<60)[r,g,b]=[c,x,0];else if(h<120)[r,g,b]=[x,c,0];else if(h<180)[r,g,b]=[0,c,x];else if(h<240)[r,g,b]=[0,x,c];else if(h<300)[r,g,b]=[x,0,c];else[r,g,b]=[c,0,x];return [r,g,b].map(n=>Math.round((n+m)*255));}
  function rgbHex(rgb){return '#'+rgb.map(n=>clamp(Math.round(n),0,255).toString(16).padStart(2,'0')).join('').toUpperCase();}
  function hexRgb(hex){const m=String(hex).replace('#','');return [parseInt(m.slice(0,2),16)||0,parseInt(m.slice(2,4),16)||0,parseInt(m.slice(4,6),16)||0];}
  function rgbToHsl([r,g,b]){r/=255;g/=255;b/=255;const max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;let h=0;const l=(max+min)/2,s=d===0?0:d/(1-Math.abs(2*l-1));if(d){if(max===r)h=60*(((g-b)/d)%6);else if(max===g)h=60*((b-r)/d+2);else h=60*((r-g)/d+4);}return[(h+360)%360,s,l];}
  function hslToHex(h,s,l){const c=(1-Math.abs(2*l-1))*s,x=c*(1-Math.abs((h/60)%2-1)),m=l-c/2;let q;if(h<60)q=[c,x,0];else if(h<120)q=[x,c,0];else if(h<180)q=[0,c,x];else if(h<240)q=[0,x,c];else if(h<300)q=[x,0,c];else q=[c,0,x];return rgbHex(q.map(v=>(v+m)*255));}
  function harmony(base,type){const [h,s,l]=rgbToHsl(hexRgb(base));const mk=(dh,ss=s,ll=l)=>hslToHex((h+dh+360)%360,clamp(ss,0,1),clamp(ll,0,1));switch(type){case'analogous':return[mk(-30),mk(0),mk(30),mk(60)];case'triad':return[mk(0),mk(120),mk(240)];case'split':return[mk(0),mk(150),mk(210)];case'tetrad':return[mk(0),mk(90),mk(180),mk(270)];case'monochrome':return[mk(0,s,.25),mk(0,s,.42),mk(0,s,.6),mk(0,s,.78)];default:return[mk(0),mk(180),mk(180,s*.55,clamp(l+.18,0,1))];}}
  function renderHarmony(){const wrap=$('mergedHarmonyPalette');if(!wrap)return;wrap.innerHTML='';for(const c of harmony(editor.brush.color||'#17252a',$('mergedHarmonySelect').value)){const b=document.createElement('button');b.type='button';b.style.background=c;b.title=`${c}: click Color 1, right-click Color 2`;b.addEventListener('click',()=>setPrimary(c));b.addEventListener('contextmenu',e=>{e.preventDefault();setSecondary(c);});wrap.appendChild(b);}}
  function setPrimary(c){editor.brush.color=c;if($('brushColorInput')){$('brushColorInput').value=c;$('brushColorInput').dispatchEvent(new Event('input',{bubbles:true}));}if($('effectsHexInput'))$('effectsHexInput').value=c;renderHarmony();}
  function setSecondary(c){editor.brush.secondaryColor=c;if($('mergedSecondaryColor'))$('mergedSecondaryColor').value=c;}
  function drawWheel(){const c=$('mergedColorWheel');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height,cx=w/2,cy=h/2,r=Math.min(w,h)/2-2,v=Number($('mergedWheelValue')?.value||100)/100,img=ctx.createImageData(w,h);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const dx=x-cx,dy=y-cy,d=Math.hypot(dx,dy),i=(y*w+x)*4;if(d<=r){const rgb=hsvToRgb((Math.atan2(dy,dx)*180/Math.PI+360)%360,Math.min(1,d/r),v);img.data[i]=rgb[0];img.data[i+1]=rgb[1];img.data[i+2]=rgb[2];img.data[i+3]=255;}}ctx.putImageData(img,0,0);}
  function wheelPick(e){const c=$('mergedColorWheel'),box=c.getBoundingClientRect(),x=(e.clientX-box.left)*c.width/box.width,y=(e.clientY-box.top)*c.height/box.height,cx=c.width/2,cy=c.height/2,dx=x-cx,dy=y-cy,r=Math.min(c.width,c.height)/2-2,d=Math.hypot(dx,dy);if(d>r)return;const color=rgbHex(hsvToRgb((Math.atan2(dy,dx)*180/Math.PI+360)%360,Math.min(1,d/r),Number($('mergedWheelValue').value)/100)),target=$('mergedColorTarget').value,s=editor.selected();if(target==='primary')setPrimary(color);else if(target==='secondary')setSecondary(color);else if(target==='canvas'){editor.setDocument({background:color},false);if($('backgroundInput'))$('backgroundInput').value=color;}else if(target==='shapeFill'&&s?.type==='shape'){s.fill=color;editor.changed('Shape fill changed');}else if(target==='shapeStroke'&&s?.type==='shape'){s.stroke=color;editor.changed('Shape outline changed');}else if(target==='textFill'&&s?.type==='text'){s.color=color;editor.changed('Text color changed');}else if(target==='textStroke'&&s?.type==='text'){s.stroke=color;editor.changed('Text outline changed');}else status('Select a matching text or shape layer for that color target.','warn');}
  function convolution(data,w,h,kernel,div=1,bias=0){const src=new Uint8ClampedArray(data),side=Math.sqrt(kernel.length)|0,half=side>>1;for(let y=0;y<h;y++)for(let x=0;x<w;x++){let rr=0,gg=0,bb=0;for(let ky=0;ky<side;ky++)for(let kx=0;kx<side;kx++){const xx=clamp(x+kx-half,0,w-1),yy=clamp(y+ky-half,0,h-1),i=(yy*w+xx)*4,k=kernel[ky*side+kx];rr+=src[i]*k;gg+=src[i+1]*k;bb+=src[i+2]*k;}const o=(y*w+x)*4;data[o]=clamp(rr/div+bias,0,255);data[o+1]=clamp(gg/div+bias,0,255);data[o+2]=clamp(bb/div+bias,0,255);}}
  function bakeEffect(name){const s=editor.selected();if(!s||s.type!=='paint'){status('Select a paint layer to bake a pixel effect. Image and text layers can use the live Effects filters.','warn');return;}editor.pushHistory();const c=renderer.getPaintCanvas(s),ctx=c.getContext('2d'),img=ctx.getImageData(0,0,c.width,c.height),d=img.data;if(name==='grayscale'||name==='invert'||name==='sepia'){for(let i=0;i<d.length;i+=4){const r=d[i],g=d[i+1],b=d[i+2];if(name==='grayscale'){const y=.299*r+.587*g+.114*b;d[i]=d[i+1]=d[i+2]=y;}else if(name==='invert'){d[i]=255-r;d[i+1]=255-g;d[i+2]=255-b;}else{d[i]=clamp(.393*r+.769*g+.189*b,0,255);d[i+1]=clamp(.349*r+.686*g+.168*b,0,255);d[i+2]=clamp(.272*r+.534*g+.131*b,0,255);}}}else if(name==='sharpen')convolution(d,c.width,c.height,[0,-1,0,-1,5,-1,0,-1,0]);else if(name==='emboss')convolution(d,c.width,c.height,[-2,-1,0,-1,1,1,0,1,2],1,128);else if(name==='edge')convolution(d,c.width,c.height,[-1,-1,-1,-1,8,-1,-1,-1,-1],1,128);ctx.putImageData(img,0,0);s.dataUrl=c.toDataURL('image/png');editor.changed(`Baked ${name} effect`);status(`${name[0].toUpperCase()+name.slice(1)} baked into the paint layer. Undo remains available.`,'ok');}
  function inject(){const pane=$('createPane');if(!pane||$('mergedDonorTools'))return;const box=document.createElement('section');box.id='mergedDonorTools';box.className='merged-donor-tools';box.innerHTML=`
    <div class="section-label">Classic Paint + AddText extras</div>
    <div class="field-row"><div class="field"><label>Color 1</label><input id="mergedPrimaryColor" type="color" value="#17252a"></div><button id="mergedSwapColors" class="color-swap" type="button" title="Swap paint colors">⇄</button><div class="field"><label>Color 2</label><input id="mergedSecondaryColor" type="color" value="#fff8e5"></div></div>
    <div class="field"><label>Brush spacing <output id="mergedBrushSpacingOut">12</output>%</label><input id="mergedBrushSpacing" type="range" min="1" max="100" value="12"></div>
    <div class="field"><label>Brush hardness <output id="mergedBrushHardnessOut">80</output>%</label><input id="mergedBrushHardness" type="range" min="0" max="100" value="80"></div>
    <div class="merge-color-layout"><canvas id="mergedColorWheel" width="170" height="170" aria-label="HSV color wheel"></canvas><div><div class="field"><label>Wheel brightness</label><input id="mergedWheelValue" type="range" min="10" max="100" value="100"></div><div class="field"><label>Apply wheel to</label><select id="mergedColorTarget"><option value="primary">Paint Color 1</option><option value="secondary">Paint Color 2</option><option value="shapeFill">Shape fill</option><option value="shapeStroke">Shape outline</option><option value="textFill">Text fill</option><option value="textStroke">Text outline</option><option value="canvas">Canvas color</option></select></div></div></div>
    <div class="field"><label>Color harmony</label><select id="mergedHarmonySelect"><option value="complementary">Complementary</option><option value="analogous">Analogous</option><option value="triad">Triad</option><option value="split">Split complementary</option><option value="tetrad">Tetrad</option><option value="monochrome">Monochrome</option></select></div><div id="mergedHarmonyPalette" class="program-swatches harmony-palette"></div>
    <div class="section-label">Reusable image stamp</div><input id="mergedStampFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif" class="hidden"><div class="button-grid"><button id="mergedLoadStamp" type="button">＋ Load Stamp</button><button class="editor-tool" data-editor-tool="stamp" id="mergedStampTool" type="button">▧ Stamp Tool</button></div><div class="field"><label>Stamp size <output id="mergedStampSizeOut">180</output> px</label><input id="mergedStampSize" type="range" min="10" max="1200" value="180"></div><div class="field-row"><div class="field"><label>Rotation</label><input id="mergedStampRotation" type="number" min="-360" max="360" value="0"></div><div class="field"><label>Opacity</label><input id="mergedStampOpacity" type="range" min="1" max="100" value="100"></div></div><small id="mergedStampStatus">Load one image, then click repeatedly on the cover to place editable stamp layers.</small>
    <div class="section-label">Baked paint-layer effects</div><div class="button-grid merged-filter-grid">${['grayscale','invert','sepia','sharpen','emboss','edge'].map(x=>`<button type="button" data-bake="${x}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div>
    <button id="mergedRandomizeTexture" type="button">↻ Randomize Selected Texture</button>`;pane.appendChild(box);
  }
  function bind(){
    $('mergedPrimaryColor').value=editor.brush.color||'#17252a';$('mergedSecondaryColor').value=editor.brush.secondaryColor||'#fff8e5';
    $('mergedPrimaryColor').addEventListener('input',e=>setPrimary(e.target.value));$('mergedSecondaryColor').addEventListener('input',e=>setSecondary(e.target.value));
    $('mergedSwapColors').addEventListener('click',()=>{const a=editor.brush.color,b=editor.brush.secondaryColor||'#fff8e5';setPrimary(b);setSecondary(a);$('mergedPrimaryColor').value=b;});
    $('mergedBrushSpacing').addEventListener('input',e=>{editor.brush.spacing=Number(e.target.value)/100;$('mergedBrushSpacingOut').textContent=e.target.value;});
    $('mergedBrushHardness').addEventListener('input',e=>{editor.brush.hardness=Number(e.target.value)/100;$('mergedBrushHardnessOut').textContent=e.target.value;});
    $('mergedWheelValue').addEventListener('input',drawWheel);$('mergedColorWheel').addEventListener('pointerdown',wheelPick);$('mergedHarmonySelect').addEventListener('change',renderHarmony);drawWheel();renderHarmony();
    $('mergedLoadStamp').addEventListener('click',()=>$('mergedStampFile').click());$('mergedStampFile').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;try{const src=await LF.util.readFileAsDataUrl(f),img=await LF.util.loadImage(src);editor.stamp.src=src;editor.stamp.image=img;editor.setTool('stamp');$('mergedStampStatus').textContent=`Loaded ${f.name}. Click the cover to stamp it.`;status(`Stamp loaded: ${f.name}.`,'ok');}catch(err){status(`Stamp failed: ${err.message}`,'warn');}finally{e.target.value='';}});
    $('mergedStampSize').addEventListener('input',e=>{editor.stamp.size=Number(e.target.value);$('mergedStampSizeOut').textContent=e.target.value;});$('mergedStampRotation').addEventListener('change',e=>editor.stamp.rotation=Number(e.target.value)||0);$('mergedStampOpacity').addEventListener('input',e=>editor.stamp.opacity=Number(e.target.value)/100);
    $$('#mergedDonorTools [data-editor-tool]').forEach(b=>b.addEventListener('click',()=>editor.setTool(b.dataset.editorTool)));document.addEventListener('lf:stamp-missing',()=>status('Load a stamp image before using Stamp Tool.','warn'));
    $$('#mergedDonorTools [data-bake]').forEach(b=>b.addEventListener('click',()=>bakeEffect(b.dataset.bake)));$('mergedRandomizeTexture').addEventListener('click',()=>{const s=editor.selected();if(s?.type!=='texture'){status('Select a texture layer first.','warn');return;}s.seed=Math.floor(Math.random()*2147483647);editor.changed('Texture seed randomized');status('Texture seed randomized.','ok');});
    $('artCanvas')?.addEventListener('contextmenu',e=>e.preventDefault());document.addEventListener('lf:colorpicked',e=>{if(e.detail?.color){$('mergedPrimaryColor').value=e.detail.color;renderHarmony();}});
  }
  function start(){if(started||!LF?.studioApi?.isReady?.())return;started=true;editor=LF.studioApi._getEditor();renderer=LF.studioApi._getRenderer();inject();bind();status('Merged Paint / AddText tools ready.','ok');}
  document.addEventListener('lf:studio-ready',start,{once:true});if(LF?.studioApi?.isReady?.())start();
})();
